<?php require_once '../includes/auth.php'; require_role(['distributor','shop']); $page_title='My Stock'; $uid=(int)$_SESSION['user_id']; include '../includes/header.php'; include '../includes/sidebar.php'; $q=mysqli_query($conn,"SELECT s.*,p.name,p.sku,p.barcode,p.sale_price,p.gst_percent,w.name warehouse FROM stock s JOIN products p ON p.id=s.product_id JOIN warehouses w ON w.id=s.warehouse_id WHERE s.owner_id=$uid ORDER BY p.name"); ?>
<div class="card-box"><h4>Warehouse Stock</h4><table class="table"><tr><th>Product</th><th>SKU</th><th>Barcode</th><th>Warehouse</th><th>Qty</th><th>Reorder</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($q)){ ?><tr><td><?php echo $r['name']; ?></td><td><?php echo $r['sku']; ?></td><td><?php echo $r['barcode']; ?></td><td><?php echo $r['warehouse']; ?></td><td><?php echo $r['quantity']; ?></td><td><?php echo $r['reorder_level']; ?></td><td><?php echo $r['quantity'] <= $r['reorder_level'] ? '<span class="text-danger fw-bold">Low</span>' : '<span class="text-success fw-bold">OK</span>'; ?></td></tr><?php } ?></table></div><?php include '../includes/footer.php'; ?>
